Object.assign(window.TEM8_DICTIONARY, {"above":{"media":{"uk":"media/uk/above__gb_1.mp3","us":"media/us/above__us_1.mp3"},"oxford":{"phon":"əˈbʌv","pos":"preposition","senses":[{"en":"at or to a higher place or position than something/somebody","cn":"在（或向）…上面","ex":{"en":"The water came above our knees.","cn":"水淹过了我们的膝盖。"}},{"en":"more than something; greater in number, level or age than somebody/something","cn":"（数目、数量、水平、年龄）超过，多于，大于","ex":{"en":"Inflation is above 6%.","cn":"通货膨胀超过 6%。"}},{"en":"of greater importance or of higher quality than somebody/something","cn":"（重要性、质量）超过，胜过","ex":{"en":"I rate her above most other players of her age.","cn":"我认为她优于大多数同龄参赛者。"}},{"en":"too good or too honest to do something","cn":"（因善良或诚实正直而）不至于，不屑于（做某事）","ex":{"en":"She's not above lying when it suits her.","cn":"她在适当时机还是会说谎的。"}},{"en":"louder or clearer than another sound","cn":"（音量或清晰度）超过（另一种声音）","ex":{"en":"I couldn't hear her above the noise of the traffic.","cn":"交通嘈杂，我听不见她的声音。"}},{"en":"at or to a higher place","cn":"在（或向）上面；在（或向）较高处","ex":{"en":"Put it on the shelf above.","cn":"把它放到上面的搁板上。"},"pos":"adverb"},{"en":"greater in number, level or age","cn":"（数目、数量、水平、年龄）超过，更多，更大","ex":{"en":"increases of 5% and above","cn":"增加 5% 及以上"},"pos":"adverb"},{"en":"earlier in something written or printed","cn":"上文；前文","ex":{"en":"As was stated above…","cn":"如上所述…"},"pos":"adverb"},{"en":"mentioned or printed previously in a letter, book, etc.","cn":"前文述及的；上述的","ex":{"en":"Please write to us at the above address.","cn":"请按上述地址来函。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"在…上方;高于","en":"If one thing is above another one, it is directly over it or higher than it.","ex":{"en":"He lifted his hands above his head","cn":"他将双手举过头顶。"}},{"pos":"ADV 副词","cn":"上述;在上文","en":"In writing, you use above to refer to something that has already been mentioned or discussed.","ex":{"en":"Several conclusions could be drawn from the results described above","cn":"从上文描述的结果中可以得出几个结论。"}},{"pos":"PREP 介词","cn":"（数量或度量）在…以上，超过","en":"If an amount or measurement is above a particular level, it is greater than that level.","ex":{"en":"The temperature crept up to just above 40 degrees","cn":"温度攀升至40度出头。"}},{"pos":"PREP 介词","cn":"（声音）比…更响亮，盖过","en":"If you hear one sound above another, it is louder or clearer than the second one.","ex":{"en":"...trying to talk above the noise","cn":"努力使说话声高过噪音"}},{"pos":"PREP 介词","cn":"（社会地位或权威）高于","en":"If someone is above you, they are in a higher social position than you or in a position of authority over you.","ex":{"en":"I know you're above me socially, but I must say I find your attitude offensive","cn":"我明白你的社会地位比我高，但我得说我觉得你的态度很粗鲁。"}},{"pos":"PHRASE 短语","cn":"自视过高；妄自尊大","en":"If you say that someone is getting above themself, you disapprove of them because they think they are better than everyone else.","ex":{"en":"I just think you're getting a little bit above yourself.","cn":"我只是觉得你变得有点自视过高。"}},{"pos":"PREP 介词","cn":"（因自视甚高）不屑于","en":"If you say that someone thinks they are above something, you mean that they act as if they are too good or important for it.","ex":{"en":"This was clearly a failure by someone who thought he was above failure","cn":"这显然是认为自己根本不会失败的人所遭遇的一次失败。"}},{"pos":"PREP 介词","cn":"不会受到（批评或怀疑）；超乎…之所及","en":"If someone is above criticism or suspicion, they cannot be criticized or suspected because of their good qualities or their position.","ex":{"en":"The Queen remains above criticism, apart from the issue of her tax liability","cn":"抛开她的纳税义务不谈，女王一直无可指摘。"}},{"pos":"PREP 介词","cn":"比…更重要；胜过；优于","en":"If you value one person or thing above any other, you value them more or consider that they are more important.","ex":{"en":"...his tendency to put the team above everything","cn":"他把这个团队看得比什么都重要的倾向"}},{"pos":"","cn":"","en":"over and above→see: ; above the law→see: ; above board→see: ;"}]},"examples":[{"en":"A captain in the navy ranks above a captain in the army.","cn":"海军的 captain（上校）军衔比陆军的 captain（上尉）高。"},{"en":"They finished the year six places above their local rivals.","cn":"这一年结束，他们的排名比当地竞争对手超前六个名次。"}]},"absent-minded":{"oxford":{"phon":"ˌæbsənt ˈmaɪndɪd","pos":"adjective","senses":[{"en":"tending to forget things, perhaps because you are not thinking about what is around you, but about something else","cn":"健忘的；心不在焉的","ex":{"en":"Grandpa’s becoming quite absent-minded.","cn":"爷爷变得十分健忘。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"漫不经心的;心不在焉的;健忘的","en":"Someone who is absent-minded forgets things or does not pay attention to what they are doing, often because they are thinking about something else.","ex":{"en":"In his later life he became even more absent-minded.","cn":"他晚年变得愈加健忘了。"}}]},"media":{"uk":"media/uk/absent_minded_1_gb_1.mp3","us":"media/us/absent_minded_1_us_1.mp3"},"examples":[{"en":"Grandad’s been getting rather absent-minded lately.","cn":"爷爷最近变得越发健忘了。"}]},"absorbed":{"oxford":{"phon":"əbˈzɔːbd","pos":"adjective","senses":[{"en":"very interested in something/somebody so that you are not paying attention to anything else","cn":"被…吸引住；专心致志；全神贯注","ex":{"en":"She seemed totally absorbed in her book.","cn":"她好像完全沉浸在书中。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极感兴趣的；专心的；全神贯注的","en":"If you are absorbed in something or someone, you are very interested in them and they take up all your attention and energy.","ex":{"en":"They were completely absorbed in each other","cn":"两人彼此倾心。"}}]},"media":{"uk":"media/uk/absorbed__gb_1.mp3","us":"media/us/absorbed__us_1.mp3"},"examples":[{"en":"She seemed totally absorbed in her book.","cn":"她好像完全被这本书迷住了。"}]},"abbot":{"media":{"uk":"media/uk/abbot__gb_1.mp3","us":"media/us/abbot__us_1.mp3"},"oxford":{"phon":"ˈæbət","pos":"noun","senses":[{"en":"a man who is the head of an abbey of monks","cn":"男修院院长"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"男修道院院长；大寺院男住持","en":"An abbot is the monk who is in charge of the other monks in a monastery or abbey."}]}},"abnormal":{"oxford":{"phon":"æbˈnɔːml","pos":"adjective","senses":[{"en":"different from what is usual or expected, especially in a way that worries somebody or is harmful or not wanted","cn":"不正常的；反常的；变态的；畸形的","ex":{"en":"abnormal levels of sugar in the blood","cn":"血糖值不正常"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"反常的；异常的；不规则的","en":"Someone or something that is abnormal is unusual, especially in a way that is worrying.","ex":{"en":"...abnormal heart rhythms and high anxiety levels.","cn":"心律不齐和高度焦虑"}}]},"media":{"uk":"media/uk/abnormal__gb_1.mp3","us":"media/us/abnormal__us_1.mp3"},"examples":[{"en":"They thought his behaviour was abnormal.","cn":"他们认为他行为反常。"},{"en":"abnormal levels of sugar in the blood","cn":"血糖值不正常"}]},"absolute":{"media":{"uk":"media/uk/absolute__gb_1.mp3","us":"media/us/absolute__us_1.mp3"},"oxford":{"phon":"ˈæbsəluːt","pos":"adjective","senses":[{"en":"total and complete","cn":"完全的；全部的；绝对的","ex":{"en":"I've joined a class for absolute beginners.","cn":"我参加了一个专门为初学者开设的班。"}},{"en":"used, especially in spoken English, to give emphasis to what you are saying","cn":"（口语中尤用以强调）道地的，确实的，十足的","g":"[only before noun]","ex":{"en":"We must keep costs to an absolute minimum.","cn":"我们必须把成本控制到最低。"}},{"en":"definite and without any doubt","cn":"肯定的；无疑的；明确的","ex":{"en":"There was no absolute proof.","cn":"没有确凿的证据。"}},{"en":"(of a legal decision) final","cn":"（法律判决）最终的","ex":{"en":"The divorce became absolute last week.","cn":"离婚在上周已成定局。"}},{"en":"not limited in any way","cn":"不受限制的；不受约束的","ex":{"en":"absolute power/authority","cn":"无上权力；绝对权威"}},{"en":"existing or measured independently and not in relation to something else","cn":"独立的；绝对的","ex":{"en":"Although prices are falling in absolute terms, energy is still expensive.","cn":"尽管能源的绝对售价在下降，但仍然昂贵。"}},{"en":"an idea or a principle that is believed to be true or relevant in any circumstances","cn":"绝对（指思想或原理）","ex":{"en":"Right and wrong are, for her, moral absolutes.","cn":"她认为，是与非是道德上的绝对准则。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"完全的；彻底的","en":"Absolute means total and complete.","ex":{"en":"It's not really suited to absolute beginners","cn":"它并不真正适合从零开始的初学者。"}},{"pos":"ADJ 形容词","cn":"十足的；地道的","en":"You use absolute to emphasize something that you are saying.","ex":{"en":"About 12 inches wide is the absolute minimum you should consider","cn":"12英寸左右的宽度绝对是你应考虑的最低值。"}},{"pos":"ADJ 形容词","cn":"专制独裁的；有无上权力的","en":"An absolute ruler has complete power and authority over his or her country.","ex":{"en":"He ruled with absolute power.","cn":"他实行独裁统治。"}},{"pos":"ADJ 形容词","cn":"确实的；不容置疑的","en":"Absolute is used to say that something is definite and will not change even if circumstances change.","ex":{"en":"John brought the absolute proof that we needed","cn":"约翰带来了我们所需的确凿证据。"}},{"pos":"ADJ 形容词","cn":"（数值）不受变量影响的，绝对的","en":"An amount that is expressed in absolute terms is expressed as a fixed amount rather than referring to variable factors such as what you earn or the effects of inflation.","ex":{"en":"In absolute terms British wages remain low by European standards.","cn":"根据欧洲标准，英国工资的绝对值依然很低。"}},{"pos":"ADJ 形容词","cn":"（规则、原则）绝对的","en":"Absolute rules and principles are believed to be true, right, or relevant in all situations.","ex":{"en":"There are no absolute rules.","cn":"世事无绝对。"}},{"pos":"N-COUNT 可数名词","cn":"绝对法则（或原则）","en":"An absolute is a rule or principle that is believed to be true, right, or relevant in all situations.","ex":{"en":"We tend to think in absolutes.","cn":"我们思考问题倾向于绝对化。"}}]},"examples":[{"en":"Although prices are falling in absolute terms , energy is still expensive.","cn":"尽管能源的绝对售价在下降，但仍然昂贵。"},{"en":"He taught us that the laws of physics were absolute.","cn":"他教导我们说，物理定律是确实存在的。"}]},"absorbs":{"oxford":{"phon":"əbˈsɔːb","pos":"verb","senses":[{"en":"to take in a liquid, gas or other substance from the surface or space around","cn":"吸收（液体、气体等）"},{"en":"to make sth smaller become part of sth larger","cn":"使并入；吞并；同化"}]},"media":{"uk":"media/uk/absorb__gb_1.mp3","us":"media/us/absorb__us_1.mp3"}},"abandoned":{"media":{"uk":"media/uk/abandoned__gb_1.mp3","us":"media/us/abandoned__us_1.mp3"},"oxford":{"phon":"əˈbændənd","pos":"adjective","senses":[{"en":"left and no longer wanted, used or needed","cn":"被离弃的；被遗弃的；被抛弃的","ex":{"en":"an abandoned car/house","cn":"被抛弃的轿车；弃置的房子"}},{"en":"(of people or their behaviour) wild; not following accepted standards","cn":"放纵的；堕落的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(场所或建筑物)舍弃不用的，无人居住的","en":"An abandoned place or building is no longer used or occupied.","ex":{"en":"All that digging had left a network of abandoned mines and tunnels.","cn":"东挖西掘后留下了一片废弃的矿坑。"}}]},"examples":[{"en":"The child was found abandoned but unharmed.","cn":"该弃儿被人们发现时安然无恙。"},{"en":"an abandoned car/house","cn":"被抛弃的轿车；弃置的房子"}]},"abominable":{"media":{"uk":"media/uk/abominable__gb_1.mp3","us":"media/us/abominable__us_1.mp3"},"oxford":{"phon":"əˈbɒmɪnəbl","pos":"adjective","senses":[{"en":"extremely unpleasant and causing horror","cn":"令人憎恶的；令人厌恶的；极为恶劣的","ex":{"en":"The judge described the attack as an abominable crime.","cn":"法官称那次袭击为令人发指的罪行。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可恶的；恶劣的；极糟的","en":"Something that is abominable is very unpleasant or bad.","ex":{"en":"The President described the killings as an abominable crime","cn":"总统称这些血案为令人发指的罪行。"}}]},"examples":[{"en":"The judge described the attack as an abominable crime.","cn":"法官称那次袭击为令人发指的罪行。"},{"en":"We were served the most abominable coffee.","cn":"给我们喝的是最劣质的咖啡。"}]},"absolutely":{"media":{"uk":"media/uk/absolutely__gb_1.mp3","us":"media/us/absolutely__us_1.mp3"},"oxford":{"phon":"ˈæbsəluːtli","pos":"adverb","senses":[{"en":"used to emphasize that something is completely true","cn":"（强调真实无误）绝对地，完全地","ex":{"en":"You're absolutely right.","cn":"你完全正确。"}},{"en":"used to emphasize something negative","cn":"绝对不；完全没有","ex":{"en":"That man does absolutely no work!","cn":"那个人一丁点活儿也没干！"}},{"en":"used with adjectives or verbs that express strong feelings or extreme qualities to mean ‘extremely’","cn":"极其","ex":{"en":"absolutely delighted/thrilled","cn":"极其兴奋／激动"}},{"en":"used to emphasize that you agree with somebody, or to give somebody permission to do something","cn":"（强调同意或允许）当然，对极了","ex":{"en":"‘They could have told us, couldn't they?’ ‘Absolutely!’","cn":"“他们本来可以告诉我们的，不是吗？”“当然！”"}},{"en":"used to emphasize that you strongly disagree with somebody, or to refuse permission","cn":"（强调坚决不同意或不允许）当然不，绝对不行","ex":{"en":"‘Was it any good?’ ‘No, absolutely not.’","cn":"“那有什么好处吗？”“绝对没有。”"}},{"en":"not considered in relation to other things","cn":"绝对的；就本身而言的","ex":{"en":"White-collar crime increased both absolutely and in comparison with other categories.","cn":"无论是与其他类型犯罪相比，还是就其本身而言，白领犯罪的数量都有所增长。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"完全地；彻底地","en":"Absolutely means totally and completely.","ex":{"en":"Jill is absolutely right","cn":"吉尔完全正确。"}},{"pos":"ADV 副词","cn":"（用于强调）确实地，绝对地","en":"Some people say absolutely as an emphatic way of saying yes or of agreeing with someone. They say absolutely not as an emphatic way of saying no or of disagreeing with someone.","ex":{"en":"'It's worrying, isn't it?' – 'Absolutely.'","cn":"“这让人担忧，不是吗？”——“确实是。”"}}]},"examples":[{"en":"‘They could have told us, couldn't they?’ ‘Absolutely!’ “","cn":"他们本来可以告诉我们的，不是吗？” “当然！”"},{"en":"‘Can we leave a little early?’ ‘Absolutely!’ “","cn":"我们可以早一点离开吗？” “完全可以！”"}]},"abrupt":{"media":{"uk":"media/uk/abrupt__gb_1.mp3","us":"media/us/abrupt__us_1.mp3"},"oxford":{"phon":"əˈbrʌpt","pos":"adjective","senses":[{"en":"sudden and unexpected, often in an unpleasant way","cn":"突然的；意外的","ex":{"en":"an abrupt change/halt/departure","cn":"突然改变；骤然停顿；突然离去"}},{"en":"speaking or acting in a way that seems rude and unfriendly; not taking time to say more than is necessary","cn":"（言语、行为）粗鲁的，莽撞的，唐突的；生硬的","ex":{"en":"an abrupt manner","cn":"唐突的举止"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"突然的，意外的（常指令人不快的改变或行为）","en":"An abrupt change or action is very sudden, often in a way which is unpleasant.","ex":{"en":"Rosie's idyllic world came to an abrupt end when her parents' marriage broke up","cn":"父母婚姻的破裂使得罗茜田园诗般美好的世界陡然画上了句号。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（言语）粗鲁的，唐突的，鲁莽的","en":"Someone who is abrupt speaks in a rather rude, unfriendly way.","ex":{"en":"He was abrupt to the point of rudeness","cn":"他的唐突已到了无礼的地步。"}}]},"examples":[{"en":"She was very abrupt with me in our meeting.","cn":"我们会面时，她跟我说话非常生硬。"},{"en":"an abrupt change/halt/departure","cn":"突然改变；骤然停顿；拂袖而去"}]},"abandon":{"oxford":{"phon":"əˈbændən","pos":"verb","senses":[{"en":"to leave somebody, especially somebody you are responsible for, with no intention of returning","cn":"（不顾责任、义务等）离弃，遗弃，抛弃","ex":{"en":"The baby had been abandoned by its mother.","cn":"这个婴儿被母亲遗弃了。"}},{"en":"to leave a thing or place, especially because it is impossible or dangerous to stay","cn":"（不得已而）舍弃，丢弃，离开","ex":{"en":"Snow forced many drivers to abandon their vehicles.","cn":"大雪迫使许多驾驶者弃车步行。"}},{"en":"to stop doing something, especially before it is finished; to stop having something","cn":"中止；放弃；不再有","ex":{"en":"They abandoned the match because of rain.","cn":"因为下雨，他们中止了比赛。"}},{"en":"to stop supporting or helping somebody; to stop believing in something","cn":"停止（支持或帮助）；放弃（信念）","ex":{"en":"The country abandoned its political leaders after the war.","cn":"战后该国人民不再拥护他们的政治领袖。"}},{"en":"to feel an emotion so strongly that you can feel nothing else","cn":"陷入，沉湎于（某种情感）","lab":"literary","ex":{"en":"He abandoned himself to despair.","cn":"他陷入绝望。"}},{"en":"a way of behaving that is not sensible and shows that you do not care about the possible results of your actions or what other people think","cn":"放任；放纵","ex":{"en":"He spent money with careless abandon.","cn":"他胡乱花钱。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"离弃；遗弃；抛弃","en":"If you abandon a place, thing, or person, you leave the place, thing, or person permanently or for a long time, especially when you should not do so.","ex":{"en":"He claimed that his parents had abandoned him","cn":"他声称父母遗弃了他。"}},{"pos":"VERB 动词","cn":"中途放弃，中止（活动、工作等）","en":"If you abandon an activity or piece of work, you stop doing it before it is finished.","ex":{"en":"The authorities have abandoned any attempt to distribute food","cn":"当局中止了分发食物的尝试。"}},{"pos":"VERB 动词","cn":"放弃（想法或思路）","en":"If you abandon an idea or way of thinking, you stop having that idea or thinking in that way.","ex":{"en":"Logic had prevailed and he had abandoned the idea.","cn":"最终理智占了上风，他打消了那个念头。"}},{"pos":"VERB 动词","cn":"放纵；使沉湎于","en":"If you abandon yourself to an emotion, you think about it a lot and feel it strongly, especially when other people might think you are wrong to do so.","ex":{"en":"We are scared to abandon ourselves to our feelings in case we seem weak or out of control.","cn":"我们不敢放纵自己的情感，以免显得太过软弱或缺乏自制。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"放任；放纵","en":"If you say that someone does something with abandon, you mean that they behave in a wild, uncontrolled way and do not think or care about how they should behave.","ex":{"en":"He has spent money with gay abandon","cn":"他肆意挥霍钱财。"}},{"pos":"PHRASE 短语","cn":"（船舶下沉时）弃船","en":"If people abandon ship, they get off a ship because it is sinking.","ex":{"en":"The officers and crew prepared to abandon ship in an orderly fashion.","cn":"全体船员秩序井然地准备弃船。"}}]},"media":{"uk":"media/uk/abandon__gb_1.mp3","us":"media/us/abandon__us_1.mp3"},"examples":[{"en":"The study showed a deep fear among the elderly of being abandoned to the care of strangers.","cn":"研究表明，老人十分害怕被丢给陌生人照管。"},{"en":"The country abandoned its political leaders after the war.","cn":"战后该国人民不再拥护他们的政治领袖。"}]},"abs":{"oxford":{"phon":"æbz","pos":"noun","senses":[{"en":"the muscles of the abdomen","cn":"腹肌"},{"en":"anti-lock braking system","cn":"防抱死装置","pos":"abbreviation"}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"同abdominals","en":"Abs are the same as abdominals .","ex":{"en":"Throughout the exercise, focus on keeping your abs tight.","cn":"整个锻炼过程中，注意要紧绷腹肌。"}}]},"media":{"uk":"media/uk/abs__gb_1.mp3","us":"media/us/abs__us_1.mp3"},"examples":[{"en":"exercises that improve your legs and abs","cn":"锻炼腿部和腹肌的运动"}]},"abduction":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if soldiers, the police etc take someone away , they force that person to go with them","cn":""},{"en":"to take someone away by force, especially a child or young person, often in order to kill them or sexually attack them - used especially in news reports","cn":""}]},"examples":[{"en":"The diplomat was abducted on his way to the airport.","cn":"","src":"ld"}],"media":{"uk":"media/uk/abduction__gb_1.mp3","us":"media/us/abduction__us_1.mp3"},"oxford":{"phon":"æbˈdʌkʃn","pos":"noun","senses":[{"en":"the act of taking somebody away illegally, especially using force","cn":"诱拐；劫持；绑架","ex":{"en":"child abduction","cn":"拐带儿童"}}]}},"abruptly":{"oxford":{"phon":"əˈbrʌptli","pos":"adverb","senses":[{"en":"in a sudden, unexpected and often unpleasant way","cn":"以一种突然的、意想不到的并且经常是不愉快的方式","ex":{"en":"The interview ended abruptly.","cn":"采访戛然而止。"}},{"en":"in a way that seems rude and unfriendly, without taking time to say more than is necessary","cn":"以一种看起来很粗鲁和不友好的方式，不花时间说更多必要的东西","ex":{"en":"‘Come here!’ she said abruptly.","cn":"“过来！”她突然说道。"}}]},"media":{"uk":"media/uk/abruptly__gb_1.mp3","us":"media/us/abruptly__us_1.mp3"},"examples":[{"en":"She stopped abruptly and looked at him.","cn":"她突然停下，注视着他。"},{"en":"He spoke abruptly, as if he wanted to avoid the subject.","cn":"他说得很生硬，似乎想避开这个话题。"}]},"about":{"media":{"uk":"media/uk/about__gb_1.mp3","us":"media/us/about__us_1.mp3"},"oxford":{"phon":"əˈbaʊt","pos":"preposition","senses":[{"en":"on the subject of somebody/something; in connection with somebody/something","cn":"关于；对于","ex":{"en":"a book about flowers","cn":"一本关于花卉的书"}},{"en":"used to describe the purpose or an aspect of something","cn":"目的是；为了；涉及…方面","ex":{"en":"Movies are all about making money these days.","cn":"当今电影只顾赚钱。"}},{"en":"busy with something; doing something","cn":"忙于；从事于","ex":{"en":"Everywhere people were going about their daily business.","cn":"无论哪里，人们都在忙着干日常工作。"}},{"en":"in many directions in a place; here and there","cn":"在…到处；在…各处","lab":"especially British English","ex":{"en":"We wandered about the town for an hour or so.","cn":"我们在城里到处游逛了一个小时左右。"}},{"en":"in various parts of a place; here and there","cn":"在…四处","lab":"especially British English","ex":{"en":"The papers were strewn about the room.","cn":"房间里四处乱扔着文件。"}},{"en":"next to a place or person; in the area mentioned","cn":"在…附近；在…地方","lab":"especially British English","ex":{"en":"She's somewhere about the office.","cn":"她在办公室附近。"}},{"en":"surrounding somebody/something","cn":"围绕","lab":"literary","ex":{"en":"She wore a shawl about her shoulders.","cn":"她披了一件披肩。"}},{"en":"a little more or less than; a little before or after","cn":"大约；左右","ex":{"en":"It costs about $10.","cn":"这大约要花 10 美元。"},"pos":"adverb"},{"en":"nearly; very close to","cn":"将近；几乎","ex":{"en":"I'm just about ready.","cn":"我就要准备好了。"},"pos":"adverb"},{"en":"in many directions; here and there","cn":"到处；处处；各处","lab":"especially British English","ex":{"en":"The children were rushing about in the garden.","cn":"孩子们在花园里跑来跑去。"},"pos":"adverb"},{"en":"in no particular order; in various places","cn":"凌乱地；四处；到处","lab":"especially British English","ex":{"en":"Her books were lying about on the floor.","cn":"她的书在地板上东一本西一本地放着。"},"pos":"adverb"},{"en":"doing nothing in particular","cn":"闲着；无所事事","lab":"especially British English","ex":{"en":"People were standing about in the road.","cn":"人们在路上闲站着。"},"pos":"adverb"},{"en":"able to be found in a place","cn":"在某地；附近；周围","lab":"especially British English","ex":{"en":"There was nobody about.","cn":"附近没有人。"},"pos":"adverb"},{"en":"facing the opposite direction","cn":"向后转；掉转方向；掉头","lab":"specialist or formal","ex":{"en":"He brought the ship about.","cn":"他掉转船头。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"关于;对于;涉及;在…方面","en":"You use about to introduce who or what something relates to or concerns.","ex":{"en":"She came in for a coffee, and told me about her friend Shona","cn":"她进来喝了杯咖啡，并向我谈起了她的朋友肖纳。"}},{"pos":"PREP 介词","cn":"包含;目的是;为了","en":"When you mention the things that an activity or institution is about, you are saying what it involves or what its aims are.","ex":{"en":"Leadership is about the ability to implement change.","cn":"领导才能就是要有实施变革的能力。"}},{"pos":"PREP 介词","cn":"对…表示（情绪或心态）","en":"You use about after some adjectives to indicate the person or thing that a feeling or state of mind relates to.","ex":{"en":"'I'm sorry about Patrick,' she said","cn":"“我为帕特里克感到难过，”她说。"}},{"pos":"PREP 介词","cn":"针对（问题）","en":"If you do something about a problem, you take action in order to solve it.","ex":{"en":"Rachel was going to do something about Jacob","cn":"蕾切尔将对雅各布有所行动。"}},{"pos":"PREP 介词","cn":"（某人或某事物）具有（某种特性）","en":"When you say that there is a particular quality about someone or something, you mean that they have this quality.","ex":{"en":"There was a warmth and passion about him I never knew existed","cn":"他身上有一股我从不知道的热情和激情。"}},{"pos":"ADV 副词","cn":"大约;左右","en":"About is used in front of a number to show that the number is not exact.","ex":{"en":"In my local health centre there's about forty parking spaces","cn":"我们本地的保健中心约有40个停车位。"}},{"pos":"ADV 副词","cn":"四下；到处","en":"If someone or something moves about, they keep moving in different directions.","ex":{"en":"Everyone was running about.","cn":"大家都在跑来跑去。"}},{"pos":"PREP 介词","cn":"围绕；环绕","en":"If you put something about a person or thing, you put it around them.","ex":{"en":"Helen threw her arms about him","cn":"海伦张开双臂拥抱他。"}},{"pos":"ADJ 形容词","cn":"在手头的;现成的;能得到的","en":"If someone or something is about, they are present or available.","ex":{"en":"There's lots of money about these days for schemes like this.","cn":"近来这类计划资金充足。"}},{"pos":"ADJ 形容词","cn":"即将（做…）的；快要（发生…）的","en":"If you are about to do something, you are going to do it very soon. If something is about to happen, it will happen very soon.","ex":{"en":"I think he's about to leave","cn":"我看他要走了。"}},{"pos":"","cn":"","en":"how about→see: ; what about→see: ; just about→see: ;"},{"pos":"PHRASE 短语","cn":"（尤指一段时间无法自由行动后）四处走动，外出活动","en":"If someone is out and about, they are going out and doing things, especially after they have been unable to for a while.","ex":{"en":"Despite considerable pain she has been getting out and about almost as normal","cn":"尽管还很痛，她已经基本上行动如常。"}},{"pos":"PHRASE 短语","cn":"（常因工作）奔波","en":"If someone is out and about, they are going to a lot of different places, often as part of their job.","ex":{"en":"They often saw me out and about.","cn":"他们经常看见我四处奔波。"}}]},"examples":[{"en":"‘Anything else?’ ‘No, that's about it for now.’ “","cn":"还有什么要说的吗？” “没有了，现在我要说的就是这些。”"},{"en":"I've never done any cooking and I'm not about to start now.","cn":"我从来没有做过饭，也不想从现在开始做起来。"}]},"abstract":{"media":{"uk":"media/uk/abstract__gb_1.mp3","us":"media/us/abstract__us_1.mp3","img":["media/ldoce/img/abstract.jpg"]},"oxford":{"phon":"ˈæbstrækt","pos":"adjective","senses":[{"en":"based on general ideas and not on any particular real person, thing or situation","cn":"抽象的（与个别情况相对）；纯理论的","ex":{"en":"abstract knowledge/principles","cn":"理论知识；抽象原理"}},{"en":"existing in thought or as an idea but not having a physical reality","cn":"抽象的（与具体经验相对）","ex":{"en":"We may talk of beautiful things but beauty itself is abstract.","cn":"我们尽可谈论美的事物，但美本身却是抽象的。"}},{"en":"not representing people or things in a realistic way, but expressing the artist’s ideas about them","cn":"抽象（派）的","ex":{"en":"the work of American abstract expressionists like Mark Rothko","cn":"马克·罗斯科等美国抽象表现主义者的作品"}},{"en":"an abstract work of art","cn":"抽象派艺术作品","ex":{"en":"Kandinsky’s first pure abstracts are marked by their wild colour.","cn":"康定斯基的第一批纯抽象作品以其狂野的色彩而著称。"},"pos":"noun"},{"en":"a short piece of writing containing the main ideas in a document","cn":"（文献等的）摘要，概要","ex":{"en":"Abstracts of about 300 words should be submitted to the conference committee who will decide which papers to accept.","cn":"投稿摘要300字左右，由会议委员会决定录用。"},"pos":"noun"},{"en":"to remove something from somewhere","cn":"把…抽象出；提取；抽取；分离","ex":{"en":"She abstracted the main points from the argument.","cn":"她提炼出论证的要点。"},"pos":"verb"},{"en":"to make a written summary of a book, etc.","cn":"写出（书等）的摘要","lab":"specialist","pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"抽象的；纯概念的","en":"An abstract idea or way of thinking is based on general ideas rather than on real things and events.","ex":{"en":"...abstract principles such as justice","cn":"正义等抽象原则"}},{"pos":"PHRASE 短语","cn":"大体上；理论上；抽象地","en":"When you talk or think about something in the abstract, you talk or think about it in a general way, rather than considering particular things or events.","ex":{"en":"Money was a commodity she never thought about except in the abstract.","cn":"钱对她来说就是个抽象的东西，她从不去想钱。"}},{"pos":"ADJ 形容词","cn":"（名词)抽象的，表示抽象概念的","en":"In grammar, an abstract noun refers to a quality or idea rather than to a physical object.","ex":{"en":"...abstract words such as glory, honor, and courage.","cn":"抽象名词，如光荣、荣耀和勇气"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（艺术)抽象（派）的","en":"Abstract art makes use of shapes and patterns rather than showing people or things.","ex":{"en":"...a modern abstract painting.","cn":"一幅现代派抽象画"}},{"pos":"N-COUNT 可数名词","cn":"抽象派艺术作品","en":"An abstract is an abstract work of art."},{"pos":"N-COUNT 可数名词","cn":"摘要;梗概","en":"An abstract of an article, document, or speech is a short piece of writing that gives the main points of it."},{"pos":"VERB 动词","cn":"提取；抽取；摘取","en":"If you abstract something from a place, you take it from there.","ex":{"en":"...a licence to abstract water from the River Axe","cn":"从阿克斯河中抽水的许可证"}}]},"examples":[{"en":"We may talk of beautiful things but beauty itself is abstract.","cn":"我们尽可谈论美的事物，但美本身却是抽象的。"},{"en":"The research shows that pre-school children are capable of thinking in abstract terms.","cn":"研究显示，学前儿童具有抽象思维的能力。"}]},"ability":{"media":{"uk":"media/uk/ability__gb_1.mp3","us":"media/us/ability__us_1.mp3"},"oxford":{"phon":"əˈbɪləti","pos":"noun","senses":[{"en":"the fact that somebody/something is able to do something","cn":"能力","g":"[singular]","ex":{"en":"People with the disease may lose their ability to communicate.","cn":"这种病的患者可能会丧失与人交流的能力。"}},{"en":"a level of skill or intelligence","cn":"才能；本领；才智","g":"[uncountable, countable]","ex":{"en":"Their athletic ability is stunning.","cn":"他们的运动能力惊人。"}},{"en":"the quality of being able to be or having to be","cn":"可…性；具备…的性质","ex":{"en":"capability","cn":"能力"},"pos":"suffix"},{"en":"the fact of having the quality mentioned","cn":"适应性","ex":{"en":"changeability","cn":"可变性"},"pos":"suffix"}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"能力","en":"Your ability to do something is the fact that you can do it.","ex":{"en":"The public never had faith in his ability to handle the job","cn":"公众从来不相信他有能力胜任这一职位。"}},{"pos":"N-VAR 可变名词","cn":"才能;技能;本领","en":"Your ability is the quality or skill that you have which makes it possible for you to do something.","ex":{"en":"Her drama teacher spotted her ability","cn":"她的戏剧老师发现了她的才能。"}},{"pos":"PHRASE 短语","cn":"尽…所能地；竭尽全力地","en":"If you do something to the best of your abilities or to the best of your ability, you do it as well as you can.","ex":{"en":"I take care of them to the best of my abilities","cn":"我尽我所能地照顾他们。"}}]},"examples":[{"en":"Everyone has the right to good medical care regardless of their ability to pay.","cn":"无论支付能力如何，每个人都有权得到良好的医疗照顾。"},{"en":"A gentle form of exercise will increase your ability to relax.","cn":"和缓的运动锻炼会提高自我放松的能力。"}]},"aboard":{"media":{"uk":"media/uk/aboard__gb_1.mp3","us":"media/us/aboard__us_1.mp3"},"oxford":{"phon":"əˈbɔːd","pos":"adverb, preposition","senses":[{"en":"on or onto a ship, plane, bus or train","cn":"在（船、飞机、公共汽车、火车等）上；上（船、飞机、公共汽车、火车等）","ex":{"en":"We went aboard.","cn":"我们上了船。"}}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"在（船、飞机等）上","en":"If you are aboard a ship or plane, you are on it or in it.","ex":{"en":"She invited 750 people aboard the luxury yacht, the Savarona","cn":"她邀请了750人乘坐豪华游艇“萨瓦罗纳”号。"}}]},"examples":[{"en":"All aboard! (= the bus, boat, etc. is leaving soon)","cn":"请大家上车（或船等）！（表示马上就要开了）"},{"en":"The plane crashed, killing all 157 passengers aboard.","cn":"飞机坠毁，机上 157 名乘客全部遇难。"}]},"absorb":{"media":{"uk":"media/uk/absorb__gb_1.mp3","us":"media/us/absorb__us_1.mp3"},"oxford":{"phon":"əbˈzɔːb","pos":"verb","senses":[{"en":"to take in a liquid, gas or other substance from the surface or space around","cn":"吸收（液体、气体等）","sc":"liquid/gas","ex":{"en":"Plants absorb carbon dioxide from the air.","cn":"植物吸收空气中的二氧化碳。"}},{"en":"to take in and keep heat, light, energy, sound, etc. instead of reflecting it","cn":"吸收（热、光、能、声等）","sc":"heat/light/energy/sound","ex":{"en":"Black walls absorb a lot of heat during the day.","cn":"黑色墙壁在白天吸收大量的热。"}},{"en":"to reduce the effect of a physical impact or movement","cn":"减轻（撞击、活动等的）作用","sc":"shock/impact","ex":{"en":"This tennis racket absorbs shock on impact.","cn":"这款网球拍能减轻撞击所产生的剧烈震动。"}},{"en":"to take something into the mind and learn or understand it","cn":"理解；掌握","sc":"information","ex":{"en":"It's a lot of information to absorb all at once.","cn":"要一下子消化这些资料，真是很多。"}},{"en":"to interest somebody very much so that they pay no attention to anything else","cn":"吸引全部注意力；使全神贯注","sc":"interest somebody","ex":{"en":"This work had absorbed him for several years.","cn":"这项工作曾使他沉迷了好几年。"}},{"en":"to make something smaller become part of something larger","cn":"使并入；吞并；同化","g":"[often passive]","sc":"make part of something larger","ex":{"en":"The town absorbs an influx of tourists every summer.","cn":"每年夏天，游客会大量涌入该镇。"}},{"en":"to use up a large supply of something, especially money or time","cn":"耗费，耗去（大量金钱、时间等）","sc":"money/time/changes","ex":{"en":"The new proposals would absorb $80 billion of the federal budget.","cn":"这些新提案将耗费 800 亿美元联邦政府预算。"}},{"en":"to deal with changes, effects, costs, etc.","cn":"承受，承担，对付（变化、结果、费用等）","sc":"money/time/changes","ex":{"en":"The company is unable to absorb such huge losses.","cn":"公司无法承受如此巨大的损失。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"吸收（液体、气体等）","en":"If something absorbs a liquid, gas, or other substance, it soaks it up or takes it in.","ex":{"en":"Plants absorb carbon dioxide from the air and moisture from the soil","cn":"植物从空气中吸收二氧化碳并从土壤中汲取水分。"}},{"pos":"VERB 动词","cn":"吸收（光、热等能量）","en":"If something absorbs light, heat, or another form of energy, it takes it in.","ex":{"en":"A household radiator absorbs energy in the form of electric current and releases it in the form of heat.","cn":"家用取暖器吸收电流能量，再以热量的形式释放出来。"}},{"pos":"VERB 动词","cn":"合并；兼并；吸收并同化","en":"If a group is absorbed into a larger group, it becomes part of the larger group.","ex":{"en":"The Colonial Office was absorbed into the Foreign Office.","cn":"殖民部被并入了外交部。"}},{"pos":"VERB 动词","cn":"消减，缓冲（外力、震动等）","en":"If something absorbs a force or shock, it reduces its effect.","ex":{"en":"...footwear which does not absorb the impact of the foot striking the ground.","cn":"不具备减震功能的鞋子"}},{"pos":"VERB 动词","cn":"经受，承受（变革、影响等）；承担（费用等）","en":"If a system or society absorbs changes, effects, or costs, it is able to deal with them.","ex":{"en":"The banks would be forced to absorb large losses","cn":"银行将被迫承受巨大的损失。"}},{"pos":"VERB 动词","cn":"用掉，花掉（大量金钱）；占去（空间、时间）","en":"If something absorbs something valuable such as money, space, or time, it uses up a great deal of it.","ex":{"en":"It absorbed vast amounts of capital that could have been used for investment","cn":"它消耗掉了原本可用于投资的大笔资金。"}},{"pos":"VERB 动词","cn":"理解，掌握（信息）","en":"If you absorb information, you learn and understand it.","ex":{"en":"Too often he only absorbs half the information in the manual","cn":"他对于说明书上所说的经常是一知半解。"}},{"pos":"VERB 动词","cn":"吸引…的注意；使全神贯注","en":"If something absorbs you, it interests you a great deal and takes up all your attention and energy.","ex":{"en":"...a second career which absorbed her more completely than her acting ever had.","cn":"比演艺生涯更让她投入的又一职业"}}]},"examples":[{"en":"The new proposals would absorb $80 billion of the federal budget.","cn":"这些新提案将耗费 800 亿元联邦政府预算。"},{"en":"The country simply cannot absorb this influx of refugees.","cn":"这个国家实在没有能力接纳这么多涌入的难民。"}]},"able":{"media":{"uk":"media/uk/able__gb_1.mp3","us":"media/us/able__us_1.mp3"},"oxford":{"phon":"ˈeɪbl","pos":"adjective","senses":[{"en":"having the skill, intelligence, opportunity, etc. needed to do something","cn":"拥有做某事所需的技能、智力、机会等","ex":{"en":"You must be able to speak French for this job.","cn":"干这项工作你得会说法语。"}},{"en":"intelligent; good at something","cn":"有才智的；有才能的；（某方面）擅长的","ex":{"en":"She's the ablest student in the class.","cn":"她是班里最能干的学生。"}},{"en":"that can or must be","cn":"可…的；能…的；应…的","ex":{"en":"calculable","cn":"可计算的"},"pos":"suffix"},{"en":"having the quality of","cn":"具有…性质的","ex":{"en":"fashionable","cn":"时髦"},"pos":"suffix"}]},"collins":{"senses":[{"pos":"PHR-MODAL 情态动词短语","cn":"（因具有品质或技能）能做到…的","en":"If you are able to do something, you have skills or qualities which make it possible for you to do it.","ex":{"en":"The older child should be able to prepare a simple meal","cn":"那个年纪稍大的孩子应当会做一顿简单的饭菜。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"（因有足够的自由、权力、时间、财力等而）可以…的，能够…的","en":"If you are able to do something, you have enough freedom, power, time, or money to do it.","ex":{"en":"You'll be able to read in peace","cn":"你就能安心地读书了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"聪明能干的；能力出众的","en":"Someone who is able is very clever or very good at doing something.","ex":{"en":"...one of the brightest and ablest members of the government","cn":"政府里最聪明能干的成员之一"}},{"pos":"","cn":"","en":"→see usage note at:"}]},"examples":[{"en":"We aim to help the less able in society to lead an independent life.","cn":"我们的宗旨是帮助社会上能力较弱的人独立生活。"},{"en":"A viral illness left her barely able to walk.","cn":"一场病毒引起的疾病使她走路都十分困难。"}]},"abundant":{"media":{"uk":"media/uk/abundant__gb_1.mp3","us":"media/us/abundant__us_1.mp3"},"oxford":{"phon":"əˈbʌndənt","pos":"adjective","senses":[{"en":"existing in large quantities; more than enough","cn":"大量的；丰盛的；充裕的","ex":{"en":"Fish are abundant in the lake.","cn":"湖里鱼很多。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"大量的；丰富的；充足的","en":"Something that is abundant is present in large quantities.","ex":{"en":"There is an abundant supply of cheap labour","cn":"廉价劳动力供应充足。"}}]},"examples":[{"en":"We have abundant evidence to prove his guilt.","cn":"我们有充分的证据证明他有罪。"},{"en":"Fish are abundant in the lake.","cn":"湖里鱼很多。"}]},"abroad":{"media":{"uk":"media/uk/abroad__gb_1.mp3","us":"media/us/abroad__us_1.mp3"},"oxford":{"phon":"əˈbrɔːd","pos":"adverb","senses":[{"en":"in or to a foreign country","cn":"在国外；到国外","ex":{"en":"to go/travel/live/study abroad","cn":"出国；出国旅行；在外国居住；出国留学"}},{"en":"being talked about or felt by many people","cn":"广为流传","lab":"formal","ex":{"en":"There was news abroad that a change was coming.","cn":"盛传即将有一个变动。"}},{"en":"outside; outdoors","cn":"在室外；到室外；户外","lab":"old use"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"到国外；在国外","en":"If you go abroad, you go to a foreign country, usually one which is separated from the country where you live by an ocean or a sea.","ex":{"en":"I would love to go abroad this year, perhaps to the South of France.","cn":"我今年很想出国，可能是去法国南部。"}},{"pos":"ADV 副词","cn":"在四下流传;广为流传地","en":"If there is a story or feeling abroad, people generally know about it or feel it.","ex":{"en":"There'll still be a feeling abroad that this change has to be recognised.","cn":"人们还会普遍觉得这项变革早晚得接受。"}}]},"examples":[{"en":"She worked abroad for a year.","cn":"她在国外工作了一年。"},{"en":"There was news abroad that a change was coming.","cn":"盛传即将有一个变动。"}]},"absence":{"media":{"uk":"media/uk/absence__gb_1.mp3","us":"media/us/absence__us_1.mp3"},"oxford":{"phon":"ˈæbsəns","pos":"noun","senses":[{"en":"the fact of somebody being away from a place where they are usually expected to be; the occasion or period of time when somebody is away","cn":"缺席；不在","g":"[uncountable, countable]","ex":{"en":"The decision was made in my absence (= while I was not there).","cn":"这个决定是我不在的时候作出的。"}},{"en":"the fact of somebody/something not existing or not being available; a lack of something","cn":"不存在；缺乏","g":"[uncountable]","ex":{"en":"I was surprised by the absence of any women on the board of directors.","cn":"我真没想到董事会中竟然没有女性。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"不在；缺席","en":"Someone's absence from a place is the fact that they are not there.","ex":{"en":"...a bundle of letters which had arrived for me in my absence","cn":"我不在期间寄给我的一大堆信件"}},{"pos":"N-SING 单数名词","cn":"缺乏；不存在","en":"The absence of something from a place is the fact that it is not there or does not exist.","ex":{"en":"The presence or absence of clouds can have an important impact on heat transfer","cn":"有无云层对热量的传递会产生重要的影响。"}},{"pos":"See also:","cn":"","en":"conspicuous by one's absence→see: ;"}]},"examples":[{"en":"We did not receive any news during his long absence.","cn":"我们在他长期离开的时候没有得到一点消息。"},{"en":"The decision was made in my absence (= while I was not there).","cn":"这个决定是我不在的时候作出的。"}]},"absorbing":{"media":{"uk":"media/uk/absorbing__gb_1.mp3","us":"media/us/absorbing__us_1.mp3"},"oxford":{"phon":"əbˈzɔːbɪŋ","pos":"adjective","senses":[{"en":"interesting and fun and holding your attention completely","cn":"十分吸引人的；引人入胜的；精彩的","ex":{"en":"an absorbing book/game","cn":"一本引人入胜的书；一个极有趣的游戏"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"非常有趣的；引人入胜的","en":"An absorbing task or activity interests you a great deal and takes up all your attention and energy.","ex":{"en":"'Two Sisters' is an absorbing read","cn":"《姊妹花》的故事情节引人入胜。"}}]},"examples":[{"en":"an absorbing book/game","cn":"一本引人入胜的书；一场极有趣的游戏"},{"en":"an absorbing hobby","cn":"一项有趣的爱好"}]},"absorbent":{"media":{"uk":"media/uk/absorbent__gb_1.mp3","us":"media/us/absorbent__us_1.mp3"},"oxford":{"phon":"əbˈzɔːbənt","pos":"adjective","senses":[{"en":"able to take in something easily, especially liquid","cn":"易吸收（液体等）的","ex":{"en":"absorbent paper/materials","cn":"吸水纸；吸收性材料"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易吸收（液体）的；吸水的","en":"Absorbent material soaks up liquid easily.","ex":{"en":"The towels are highly absorbent.","cn":"这些毛巾很吸水。"}}]},"examples":[{"en":"absorbent paper/materials","cn":"吸水纸；吸收性材料"},{"en":"absorbent kitchen paper","cn":"吸水性强的厨房用纸"}]},"abbey":{"oxford":{"phon":"ˈæbi","pos":"noun","senses":[{"en":"a large church together with a group of buildings in which monks or nuns live or lived in the past","cn":"（大）隐修院；（曾为大隐修院的）大教堂","ex":{"en":"Westminster Abbey","cn":"威斯敏斯特教堂"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（大）修道院","en":"An abbey is a church with buildings attached to it in which monks or nuns live or used to live."}]},"media":{"uk":"media/uk/abbey__gb_1.mp3","us":"media/us/abbey__us_1.mp3"},"examples":[{"en":"Westminster Abbey","cn":"威斯敏斯特教堂"},{"en":"a ruined abbey","cn":"破败不堪的教堂"}]},"abstracted":{"media":{"uk":"media/uk/abstracted__gb_1.mp3","us":"media/us/abstracted__us_1.mp3"},"oxford":{"phon":"æbˈstræktɪd","pos":"adjective","senses":[{"en":"thinking deeply about something and not paying attention to what is around you","cn":"出神的；心神专注的","ex":{"en":"He was listening to music and had an abstracted expression.","cn":"他正在听音乐，表情心不在焉。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"出神的；心不在焉的","en":"Someone who is abstracted is thinking so deeply that they are not fully aware of what is happening around them.","ex":{"en":"Meg was so abstracted she scarcely noticed that the train had stopped","cn":"梅格想得出了神，几乎没有注意到火车已经停了。"}}]}},"abbreviation":{"oxford":{"phon":"əˌbriːviˈeɪʃn","pos":"noun","senses":[{"en":"a short form of a word, etc.","cn":"略语；缩写词；缩写形式","g":"[countable]","ex":{"en":"What's the abbreviation for ‘Saint’?","cn":"Saint 的缩写形式是什么？"}},{"en":"the process of abbreviating something","cn":"缩略；缩写","g":"[uncountable]"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"缩写词；缩略形式","en":"An abbreviation is a short form of a word or phrase, made by leaving out some of the letters or by using only the first letter of each word.","ex":{"en":"The postal abbreviation for Kansas is KS.","cn":"堪萨斯州的邮政缩写是KS。"}}]},"media":{"uk":"media/uk/abbreviation__gb_1.mp3","us":"media/us/abbreviation__us_1.mp3"},"examples":[{"en":"What's the abbreviation for ‘Saint’? * Saint","cn":"的缩写形式是什么？"},{"en":"What's the abbreviation for ‘Saint’?","cn":""}]},"abrasive":{"media":{"uk":"media/uk/abrasive__gb_1.mp3","us":"media/us/abrasive__us_1.mp3"},"oxford":{"phon":"əˈbreɪsɪv","pos":"adjective","senses":[{"en":"an abrasive substance is rough and can be used to clean a surface or to make it smooth","cn":"有研磨作用的；研磨的","ex":{"en":"abrasive kitchen cleaners","cn":"厨房擦洗去污剂"}},{"en":"rude and unkind; acting in a way that may hurt other people’s feelings","cn":"生硬粗暴的；粗鲁的；伤人感情的","ex":{"en":"an abrasive style/tone/comment","cn":"粗鲁的风格/语气/评论"}},{"en":"a substance used for cleaning surfaces or for making them smooth","cn":"（用来擦洗表面或使表面光滑的）磨料","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（态度）粗鲁的,不友善的","en":"Someone who has an abrasive manner is unkind and rude.","ex":{"en":"His abrasive manner has won him an unenviable notoriety","cn":"他生硬粗暴的态度让他声名狼藉。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"粗糙可用于擦洗的;有研磨作用的","en":"An abrasive substance is rough and can be used to clean hard surfaces.","ex":{"en":"...a new all-purpose, non-abrasive cleaner.","cn":"多用途的非磨砂性新型清洁剂"}},{"pos":"N-MASS 物质名词","cn":"磨料;磨蚀剂","en":"An abrasive is a substance that is rough and can be used to clean hard surfaces.","ex":{"en":"Avoid abrasives, which can damage the tiles.","cn":"避免使用磨蚀剂，以免损坏瓷砖。"}}]},"examples":[{"en":"abrasive kitchen cleaners","cn":"厨房擦洗去污剂"},{"en":"She was a tough girl with rather an abrasive manner.","cn":"她是个举止相当粗鲁的泼辣女孩。"}]},"able-bodied":{"oxford":{"phon":"ˌeɪbl ˈbɒdid","pos":"adjective","senses":[{"en":"physically healthy, fit and strong in contrast to somebody who has a health condition or disability","cn":"体格健全的，强壮的","ex":{"en":"Military service is compulsory for every able-bodied male between 18 and 27.","cn":"18至27岁体格健壮的男子必须服兵役。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"体格健全的；身强体壮的","en":"An able-bodied person is physically strong and healthy, rather than weak or disabled.","ex":{"en":"The gym can be used by both able-bodied and disabled people.","cn":"这家健身房健全和残障人士都可使用。"}}]},"media":{"uk":"media/uk/able_bodied_1_gb_1.mp3","us":"media/us/able_bodied_1_us_1.mp3"},"examples":[{"en":"Every able-bodied man had to fight for his country.","cn":"每一个体格健全的男人都必须为祖国而战斗。"}]},"abolish":{"media":{"uk":"media/uk/abolish__gb_1.mp3","us":"media/us/abolish__us_1.mp3"},"oxford":{"phon":"əˈbɒlɪʃ","pos":"verb","senses":[{"en":"to officially end a law, a system or an institution","cn":"废除，废止（法律、制度、习俗等）","ex":{"en":"This tax should be abolished.","cn":"这种税应该取消。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"废除，废止（制度、习俗等）","en":"If someone in authority abolishes a system or practice, they formally put an end to it.","ex":{"en":"The following year Parliament voted to abolish the death penalty for murder","cn":"议会于翌年表决对谋杀罪废除死刑。"}}]},"examples":[{"en":"This tax should be abolished.","cn":"这种税应该取消。"},{"en":"Slavery was abolished in the US in the 19th century.","cn":"美国于19世纪废除了奴隶制。"}]},"abilities":{"oxford":{"phon":"əˈbɪləti","pos":"noun","senses":[{"en":"the fact that sb/sth is able to do sth","cn":"能力"},{"en":"a level of skill or intelligence","cn":"才能；本领；才智"}]}},"abounding":{"oxford":{"phon":"əˈbaʊnd","pos":"verb","senses":[{"en":"to exist in great numbers or quantities","cn":"大量存在；有许多"},{"en":"to have sth in great numbers or quantities","cn":"有大量；富于"}]}},"absent":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不在的；缺席的","en":"If someone or something is absent from a place or situation where they should be or where they usually are, they are not there.","ex":{"en":"He has been absent from his desk for two weeks","cn":"他已经有两个星期没有坐在办公桌前了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"出神的;心不在焉的","en":"If someone appears absent, they are not paying attention because they are thinking about something else.","ex":{"en":"'Nothing,' Rosie said in an absent way.","cn":"“没什么，”罗茜心不在焉地说。"}},{"pos":"ADJ 形容词","cn":"（父或母）不与子女一起住的","en":"An absent parent does not live with his or her children.","ex":{"en":"...absent fathers who fail to pay towards the costs of looking after their children.","cn":"那些不在子女身边、未能支付抚养费的父亲"}},{"pos":"VERB 动词","cn":"使不在，使离开（本应在或通常在的地方）","en":"If someone absents themselves from a place where they should be or where they usually are, they do not go there or they do not stay there.","ex":{"en":"She was old enough to absent herself from the lunch table if she chose","cn":"她长大了，可以自己做主不来吃午餐了。"}},{"pos":"PREP 介词","cn":"若没有；假设没有","en":"If you say that absent one thing, another thing will happen, you mean that if the first thing does not happen, the second thing will happen.","ex":{"en":"Absent a solution, people like Sue Godfrey will just keep on fighting.","cn":"假如得不到解决，像休·戈弗雷这样的人就会一直坚持斗争下去。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if someone or something is not around they are not here or anywhere in this area, especially when they are needed","cn":""},{"en":"to not be in your home, the place where you work etc for a short time, especially when someone wants to see you","cn":""},{"en":"to not be at home, school, or work for several days or weeks, because you are travelling or staying somewhere else","cn":""}]},"vocab":{"pos":"1 adj 2 v","senses":[{"en":"Absent means not there. If you absent yourself from class, you're marked as absent . If you have an absent parent, it means they don't live with you or take part in your care."}]},"collocations":{"phrases":["VERBS be | remain","ADV. completely, entirely, quite, totally, wholly | virtually | largely | temporarily | conspicuously, markedly, notably, noticeably, striki","PREP. from He was absent from work for two weeks."]},"media":{"uk":"media/ldoce/hwd/bre/0/absent_adj0205.mp3","us":"media/ldoce/hwd/ame/9/l3absent.mp3"},"examples":[{"en":"Love was totally absent from his childhood.","cn":"他童年时根本没有受到疼爱。"},{"en":"He had absented himself from the office for the day.","cn":"这一天他没有去办公室上班。"}],"oxford":{"phon":"ˈæbsənt","pos":"adjective","senses":[{"en":"not in a place because of illness, etc.","cn":"缺席；不在","ex":{"en":"He was absent from work for two weeks.","cn":"他两个星期没有上班了。"}},{"en":"not present in something","cn":"不存在；缺少","ex":{"en":"Love was totally absent from his childhood.","cn":"他童年时没有得到丝毫关爱。"}},{"en":"showing that you are not really looking at or thinking about what is happening around you","cn":"心不在焉的；出神的","ex":{"en":"an absent expression","cn":"心不在焉的神情"}},{"en":"to not go to or be in a place where you are expected to be","cn":"缺席；不参加；不在","ex":{"en":"He had absented himself from the office for the day.","cn":"这一天他没有去办公室上班。"},"pos":"verb"},{"en":"without","cn":"无；没有","ex":{"en":"Absent further evidence, the police had no choice but to release him without charge.","cn":"由于没有进一步的证据，警方只好将他无指控释放。"},"pos":"preposition"}]}},"abode":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"住所；寓所","en":"Your abode is the place where you live.","ex":{"en":"I went round the streets and found his new abode.","cn":"我走街串巷找到了他的新住所。"}},{"pos":"PHRASE 短语","cn":"居无定所；无家可归","en":"If someone has no fixed abode, they are homeless.","ex":{"en":"30 per cent of psychiatric hospital beds are occupied by people of no fixed abode.","cn":"精神病院30%的床位是被无家可归者占据的。"}},{"pos":"PHRASE 短语","cn":"居住权；居留权","en":"If someone is given the right of abode in a particular country, they are legally allowed to live there.","ex":{"en":"Outsiders who wed islanders are given only three years' right of abode at first.","cn":"岛外的人和岛民结婚之初只能获得三年的居住权。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone’s home – sometimes used humorously","cn":"住所〔有时为幽默用法〕"},{"en":"the right to live in a country","cn":"居留权"},{"en":"the past tense of abide abide","cn":"的过去式"}]},"vocab":{"pos":"n","senses":[{"en":"Your abode is where you live. The Queen of England's abode may be far from humble, but it's the home where she rests her weary crown at the end of each day."}]},"collocations":{"phrases":["ADJ. humble (humorous) Welcome to my humble abode.","VERB + ABODE take up your (formal or humorous) I had been invited to take up my abode at Government House.","PHRASES of no fixed abode (law) (= without a permanent address) An 18-year-old man of no fixed abode appeared at Teesside magistrates court "]},"media":{"uk":"media/ldoce/hwd/bre/2/abode_n0205.mp3","us":"media/ldoce/hwd/ame/b/abode1.mp3"},"examples":[{"en":"homeless people of no fixed abode (= with no permanent home)","cn":"无家可归的人（没有固定居所）"},{"en":"You are most welcome to my humble abode.","cn":"竭诚欢迎光临寒舍。"}],"oxford":{"phon":"əˈbəʊd","pos":"noun","senses":[{"en":"the place where somebody lives","cn":"住所；家","ex":{"en":"homeless people of no fixed abode (= with no permanent home)","cn":"无家可归的人"}}]}},"abuse":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"虐待；凌辱","en":"Abuse of someone is cruel and violent treatment of them.","ex":{"en":"...investigation of alleged child abuse.","cn":"对涉嫌虐童案的调查"}},{"pos":"N-UNCOUNT 不可数名词","cn":"辱骂;恶语","en":"Abuse is extremely rude and insulting things that people say when they are angry.","ex":{"en":"I was left shouting abuse as the car sped off","cn":"汽车飞驰而去，留下我在那里大声咒骂。"}},{"pos":"N-VAR 可变名词","cn":"滥用；妄用","en":"Abuse of something is the use of it in a wrong way or for a bad purpose.","ex":{"en":"What went on here was an abuse of power.","cn":"这里所发生的事是一种滥用职权的行为。"}},{"pos":"VERB 动词","cn":"虐待;凌辱;伤害","en":"If someone is abused, they are treated cruelly and violently.","ex":{"en":"Janet had been abused by her father since she was eleven.","cn":"珍妮特从11岁起就遭受父亲虐待。"}},{"pos":"VERB 动词","cn":"辱骂;侮辱","en":"You can say that someone is abused if extremely rude and insulting things are said to them.","ex":{"en":"He alleged that he was verbally abused by other soldiers.","cn":"他宣称自己遭到其他士兵的辱骂。"}},{"pos":"VERB 动词","cn":"滥用；妄用","en":"If you abuse something, you use it in a wrong way or for a bad purpose.","ex":{"en":"He showed how the rich and powerful can abuse their position.","cn":"他让我们看到有钱有势的人是如何滥用其地位的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"cruel treatment or behaviour","cn":""},{"en":"deliberately cruel treatment of someone, especially someone in your family that you are supposed to care for","cn":""},{"en":"cruel treatment of someone who is smaller, younger, or weaker - use this especially about children being cruel to other children","cn":""}]},"vocab":{"pos":"1 n v 2 n v","senses":[{"en":"If you abuse someone, it means you are hurting that person, mentally, emotionally, or physically. If someone else is harming you, you are yourself suffering from abuse ."}]},"collocations":{"phrases":["ADJ. alcohol, drug, solvent, substance (= drugs or solvents)","VERB + ABUSE be open to The legal system is open to abuse.","PHRASES the abuse of power 2 bad, usually violent treatment of sb","ADJ. emotional, physical, sex/sexual | child, elder victims of child abuse | human rights ~s allegations of human rights abuses | alleged, s","QUANT. case six cases of suspected child abuse","VERB + ABUSE carry out, subject sb to She was subjected to regular sexual abuse. | suffer, take The child had taken a lot of emotional abuse","ABUSE + VERB happen, occur, take place","PHRASES an allegation of abuse, a perpetrator of abuse, a victim of abuse 3 insulting words"]},"media":{"uk":"media/ldoce/hwd/bre/3/abuse_n0205.mp3","us":"media/ldoce/hwd/ame/9/l3abuse.mp3"},"examples":[{"en":"He felt they had abused his trust by talking about him to the press (= tricked him, although he had trusted them).","cn":"他觉得他们向报界透露有关他的情况是辜负了他的信任。"},{"en":"He systematically abused his body with heroin and cocaine.","cn":"他因吸服海洛因和可卡因一步一步地把身体搞垮了。"}],"oxford":{"phon":"əˈbjuːs","pos":"noun","senses":[{"en":"the use of something in a way that is wrong or harmful","cn":"滥用；妄用","g":"[uncountable, singular]","ex":{"en":"alcohol/drug abuse","cn":"酗酒/吸毒"}},{"en":"unfair, cruel or violent treatment of somebody","cn":"虐待","g":"[uncountable, plural]","ex":{"en":"child abuse","cn":"虐待儿童"}},{"en":"rude and offensive remarks, usually made when somebody is very angry","cn":"辱骂；恶语","g":"[uncountable]","ex":{"en":"to scream/hurl/shout abuse","cn":"高声谩骂；破口大骂；大声辱骂"}},{"en":"to make bad use of something, or to use so much of something that it harms your health","cn":"滥用","ex":{"en":"to abuse alcohol/drugs","cn":"酗酒；嗜毒"},"pos":"verb"},{"en":"to use power or knowledge unfairly or wrongly","cn":"滥用，妄用（权力、所知所闻）","ex":{"en":"She abused her position as principal by giving jobs to her friends.","cn":"她滥用自己作为校长的职权，把工作安排给朋友们。"},"pos":"verb"},{"en":"to treat a person or an animal in a cruel or violent way, especially sexually","cn":"虐待；（尤指）性虐待；伤害","ex":{"en":"The boy had been sexually abused.","cn":"这个男孩曾遭受过性虐待。"},"pos":"verb"},{"en":"to make rude or offensive remarks to or about somebody","cn":"辱骂；对…恶语相加；诋毁","ex":{"en":"The referee had been threatened and verbally abused.","cn":"裁判遭到了恐吓和辱骂。"},"pos":"verb"}]}},"abortion":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"人工流产；堕胎","en":"If a woman has an abortion, she ends her pregnancy deliberately so that the baby is not born alive.","ex":{"en":"His girlfriend had an abortion.","cn":"他的女朋友做了流产。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if a woman has a miscarriage the baby comes out of her body far too early for it to be able to live","cn":""},{"en":"a baby that is stillborn is born dead but fully developed","cn":""},{"en":"if a baby is born dead , it is not alive when it is born","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Abortion is a surgical procedure that ends a pregnancy. In the United States, the public debate over a women's right to have an abortion is a complex and heated political issue."}]},"collocations":{"phrases":["ADJ. back-street, illegal | legal | induced, spontaneous, therapeutic","VERB + ABORTION have When she got pregnant at 16 she decided to have an abortion. | carry out, do (informal) , perform Some nurses wanted th","ABORTION + NOUN law, legislation the country's strict abortion laws | clinic, counselling","PREP. ~ on He carried out an abortion on a fifteen-year-old girl.","PHRASES abortion on demand (= the right to have an abortion if you want one) Women's groups are calling for free contraception and abortion "]},"media":{"uk":"media/ldoce/hwd/bre/5/abortion0205.mp3","us":"media/ldoce/hwd/ame/6/abortion.mp3"},"examples":[{"en":"She decided to have an abortion.","cn":"她决定做人工流产。"},{"en":"I've always been anti-abortion.","cn":"我一直反对堕胎。"}],"oxford":{"phon":"əˈbɔːʃn","pos":"noun","senses":[{"en":"the deliberate ending of a pregnancy at an early stage","cn":"人工流产；堕胎；打胎","g":"[uncountable]","ex":{"en":"to support/oppose abortion","cn":"支持／反对堕胎"}},{"en":"a medical operation to end a pregnancy at an early stage","cn":"人工流产手术；堕胎手术","g":"[countable]","ex":{"en":"She decided to have an abortion.","cn":"她决定做人工流产。"}},{"en":"the process of giving birth to a baby before it is fully developed and able to survive","cn":"流产","g":"[uncountable]","lab":"medical","ex":{"en":"Higher amounts of caffeine may be associated with increased rates of abortion and low birthweight.","cn":"较高含量的咖啡因可能与流产率增加和低出生体重有关。"}}]}},"abusive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"虐待的;凌辱的","en":"Someone who is abusive behaves in a cruel and violent way towards other people.","ex":{"en":"He became violent and abusive toward Ben's mother","cn":"他对本的妈妈动起粗来。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"侮辱性的；恶言谩骂的","en":"Abusive language is extremely rude and insulting.","ex":{"en":"He was alleged to have used abusive language.","cn":"他被指称使用过侮辱性语言。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"insulting remarks or behaviour are very rude and you feel offended by them","cn":""},{"en":"very rude and using offensive language","cn":""},{"en":"using cruel words or physical violence","cn":"谩骂的﹔虐待的"}]},"vocab":{"pos":"adj","senses":[{"en":"People or actions that are hurtful or harmful are abusive . Being abusive is one of the worst things a parent — or anyone else — can do."}]},"collocations":{"phrases":["VERBS be | become, get","ADV. very | quite | openly He became openly abusive."]},"media":{"uk":"media/ldoce/hwd/bre/d/abusive0205.mp3","us":"media/ldoce/hwd/ame/f/abusive.mp3"},"examples":[{"en":"He became abusive when he was drunk.","cn":"他喝醉时就满口脏话骂人了。"},{"en":"abusive language/remarks","cn":"秽言恶语；恶言谩骂"}],"oxford":{"phon":"əˈbjuːsɪv","pos":"adjective","senses":[{"en":"rude and offensive; criticizing rudely and unfairly","cn":"辱骂的；恶语的；毁谤的","ex":{"en":"abusive language/remarks","cn":"秽言恶语；恶言谩骂"}},{"en":"involving violence","cn":"虐待的","ex":{"en":"an abusive relationship","cn":"虐待关系"}},{"en":"involving the use of power or knowledge unfairly or wrongly","cn":"不法的；舞弊的","ex":{"en":"the abusive practices of some businesses","cn":"某些公司的不法行为"}}]}},"absurd":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"荒谬的；荒唐的；不合理的","en":"If you say that something is absurd, you are criticizing it because you think that it is ridiculous or that it does not make sense.","ex":{"en":"It is absurd to be discussing compulsory redundancy policies for teachers","cn":"讨论针对教师的强制裁员政策真是滑稽可笑。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not at all sensible or reasonable – used when you are very surprised by someone’s behaviour or what they have said","cn":""},{"en":"extremely stupid","cn":""},{"en":"extremely stupid – used especially when an idea or situation seems strange or illogical","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"Something absurd is really silly, absolutely ridiculous, or total nonsense. Thinking you can wear flip flops and a bikini to the North Pole is an absurd idea, for example."}]},"collocations":{"phrases":["VERBS be, look, seem, sound | become | find sth She found the whole concept faintly absurd.","ADV. absolutely, completely, quite, utterly | clearly, manifestly, patently | faintly, rather, slightly, somewhat | wonderfully","PHRASES a sense of the absurd His sense of the absurd kept him from becoming too solemn."]},"media":{"uk":"media/ldoce/hwd/bre/3/absurd0205.mp3","us":"media/ldoce/hwd/ame/1/absurd.mp3"},"examples":[{"en":"That uniform makes the guards look absurd.","cn":"警卫们穿着那种制服看起来怪模怪样的。"},{"en":"Of course it's not true, what an absurd idea.","cn":"那当然不合乎事实，这个想法太荒唐了！"}],"oxford":{"phon":"əbˈsɜːd","pos":"adjective","senses":[{"en":"extremely silly; not logical and sensible","cn":"荒谬的；荒唐的；怪诞不经的","ex":{"en":"That uniform makes the guards look absurd.","cn":"警卫们穿着那种制服看起来怪模怪样的。"}},{"en":"things that are or that seem to be absurd","cn":"荒诞的事物；悖理的东西","g":"[singular]","ex":{"en":"He has a good sense of the absurd.","cn":"他对荒诞事物有较强的识别能力。"}}]}},"abundance":{"collins":{"senses":[{"pos":"N-SING-COLL 单数集合名词","cn":"大量;丰富;充足","en":"An abundance of something is a large quantity of it.","ex":{"en":"The area has an abundance of wildlife","cn":"这片地区有丰富的野生动植物。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a lot of something or a lot of things or people, especially more than enough","cn":""},{"en":"more than you need - sometimes used to mean there is too much","cn":""},{"en":"a lot or more than enough of something that you need or want","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"To have an abundance of something is to have more than you need. It's often used to describe positive qualities, such as \"an abundance of love.\""}]},"collocations":{"phrases":["ADJ. great, sheer We were amazed by the sheer abundance of food. | relative","VERB + ABUNDANCE have The country has an abundance of natural resources | produce, provide","PREP. in ~ Exotic plants grew there in great abundance."]},"media":{"uk":"media/ldoce/hwd/bre/2/abundance0205.mp3","us":"media/ldoce/hwd/ame/9/abundance.mp3"},"examples":[{"en":"Fruit and vegetables grew in abundance on the island.","cn":"该岛盛产水果和蔬菜。"},{"en":"an abundance of wavy red hair","cn":"浓密的红色鬈发"}],"oxford":{"phon":"əˈbʌndəns","pos":"noun","senses":[{"en":"a large quantity that is more than enough","cn":"大量；丰盛；充裕","ex":{"en":"The brochure promised beautiful walks with an abundance of wildlife.","cn":"这本小册子许诺说可以欣赏路边美景，还可见到大量野生动物。"}}]}},"abhorrent":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人憎恶的；使人厌恶的","en":"If something is abhorrent to you, you hate it very much or consider it completely unacceptable.","ex":{"en":"Racial discrimination is abhorrent to my council and our staff","cn":"我的顾问班子和全体工作人员都对种族歧视深恶痛绝。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is abhorrent is completely unacceptable because it seems morally wrong","cn":"可恨的﹐令人憎恶的"}]},"vocab":{"pos":"adj","senses":[{"en":"Many people find cruelty toward animals abhorrent, that is, they think it's detestable, obscene, repugnant, repulsive, and offensive to the mind. In other words, they really, really don't like it."}]},"collocations":{"phrases":["VERBS be | become | find sth","ADV. totally, utterly I find the idea totally abhorrent.","PREP. to Such a savage punishment is abhorrent to a civilized society."]},"media":{"uk":"media/ldoce/hwd/bre/d/abhorrent0205.mp3","us":"media/ldoce/hwd/ame/1/abhorrent.mp3"},"examples":[{"en":"Racism is abhorrent to a civilized society.","cn":"文明社会憎恶种族主义。"},{"en":"The practice of killing animals for food is utterly abhorrent to me.","cn":"我非常痛恨杀死动物制成盘中餐的做法。"}],"oxford":{"phon":"əbˈhɒrənt","pos":"adjective","senses":[{"en":"causing a strong feeling of hate, especially for moral reasons","cn":"（尤指因道德原因）令人憎恨的，令人厌恶的，令人憎恶的","ex":{"en":"Racism is abhorrent to a civilized society.","cn":"文明社会憎恶种族主义。"}}]}},"abscess":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"脓肿","en":"An abscess is a painful swelling containing pus."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a painful swollen part of your skin or inside your body that has become infected and is full of a yellowish liquid","cn":"脓肿"}]},"vocab":{"pos":"n","senses":[{"en":"An abscess is a localized collection of pus surrounded by inflamed tissue. An abscess in a tooth is very painful and is often drained in a process called a root canal."}]},"collocations":{"phrases":["VERB + ABSCESS develop, get I developed an abscess on my neck. | burst, drain, lance | treat","ABSCESS + VERB burst Once an abscess has burst it should be bathed with antiseptic liquid."]},"media":{"uk":"media/ldoce/hwd/bre/8/abscess0205.mp3","us":"media/ldoce/hwd/ame/3/abscess.mp3"},"oxford":{"phon":"ˈæbses","pos":"noun","senses":[{"en":"a swollen (= larger than normal) and painful area on your skin or in your body, full of a thick yellow liquid (called pus)","cn":"脓肿","ex":{"en":"a painful abscess on the gum","cn":"牙龈上疼痛的脓肿"}}]}},"abraham":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"in the Old Testament of the Bible, a religious leader who is regarded as the person who established the Jews as a nation. Abraham was asked by God to kill his son Isaac as a human sacrifice because he wanted to test Abraham's faith. Then because Abraham had sh","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/p028-000001242.mp3","us":"media/ldoce/hwd/ame/c/p028-000001242.mp3"},"oxford":{"phon":"ˈeɪbrəhæm","pos":"","senses":[{"en":"a first name for boys","cn":"亚伯拉罕（男子名）"}]}},"ablaze":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"炽燃的；熊熊燃烧的","en":"Something that is ablaze is burning very fiercely.","ex":{"en":"Shops, houses, and vehicles were set ablaze.","cn":"店铺、房子和车辆全都陷于火海。"}},{"pos":"ADJ 形容词","cn":"闪耀的；闪亮的","en":"If a place is ablaze with lights or colours, it is very bright because of them.","ex":{"en":"The chamber was ablaze with light","cn":"会议厅里灯火辉煌。"}},{"pos":"ADJ 形容词","cn":"（目光、神色等）激动的，兴奋的，愤怒的","en":"If someone is ablaze, or if their eyes are ablaze, their expression shows that they are feeling a strong emotion, such as great excitement or anger.","ex":{"en":"He was ablaze with enthusiasm","cn":"他热情洋溢。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a room, house, building etc is lit up , the lights are on inside or outside","cn":""},{"en":"if a place or set of lights is ablaze , there is a lot of bright light because all the lights are turned on - used especially in literature","cn":""},{"en":"burning strongly with a lot of flames","cn":"熊熊燃烧的"}]},"vocab":{"pos":"adj","senses":[{"en":"Use the adjective ablaze to describe something that's on fire. Once your campfire is ablaze , you can toast marshmallows over it."}]},"collocations":{"phrases":["VERBS be | set sth Truck after truck was set ablaze as the fire spread.","ADV. well By the time firefighters were called the house was well ablaze."]},"media":{"uk":"media/ldoce/hwd/bre/e/ablaze0205.mp3","us":"media/ldoce/hwd/ame/0/ablaze.mp3"},"examples":[{"en":"There were lights still ablaze as they drove up to the house.","cn":"他们驾车到了屋前时，（屋内）灯火仍然通明。"},{"en":"Cars and buses were set ablaze during the riot.","cn":"暴乱中许多轿车和公共汽车被纵火焚烧。"}],"oxford":{"phon":"əˈbleɪz","pos":"adjective","senses":[{"en":"burning quickly and strongly","cn":"猛烈燃烧","ex":{"en":"The whole building was soon ablaze.","cn":"整栋大楼很快就熊熊燃烧起来。"}},{"en":"full of bright light or colours","cn":"闪耀；发光；明亮；色彩鲜艳","ex":{"en":"There were lights still ablaze as they drove up to the house.","cn":"他们驾车到屋前时，（屋内）灯火仍然通明。"}},{"en":"full of strong emotion or excitement","cn":"充满激情的；情绪激动的","ex":{"en":"He turned to her, his eyes ablaze with anger.","cn":"他转过身来，怒目圆睁瞪着她。"}}]}},"abashed":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"尴尬的；窘迫的；羞愧的","en":"If you are abashed, you feel embarrassed and ashamed.","ex":{"en":"He looked abashed, uncomfortable.","cn":"他看起来有点困窘，很不自在。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"embarrassed or ashamed because you have done something wrong or stupid","cn":"窘迫的﹐尴尬的﹐羞愧的"}]},"vocab":{"pos":"adj","senses":[{"en":"Feeling abashed is a type of embarrassment. People feel abashed when they're caught in a lie, or make a mistake, or suddenly feel self-conscious for some reason."}]},"collocations":{"phrases":["VERBS be, look","ADV. a little, slightly | suitably He glanced at Juliet accusingly and she looked suitably abashed."]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasdeabashed.mp3","us":"media/ldoce/hwd/ame/b/abashed.mp3"},"examples":[{"en":"She looked rather abashed.","cn":"她看起来很羞愧。"}],"oxford":{"phon":"əˈbæʃt","pos":"adjective","senses":[{"en":"embarrassed and ashamed because of something that you have done","cn":"羞愧；窘迫；尴尬","ex":{"en":"He glanced at Juliet accusingly and she looked suitably abashed.","cn":"他怪罪地一瞥，朱丽叶自然显得很窘。"}}]}},"aberration":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"偶发事件;非典型行为","en":"An aberration is an incident or way of behaving that is not typical.","ex":{"en":"It became very clear that the incident was not just an aberration, it was not just a single incident.","cn":"事实已经很清楚，这件事不是偶发的，它并不是一起孤立的事件。"}},{"pos":"N-VAR 可变名词","cn":"不正常的怪人；异常行为","en":"If someone considers a person or their behaviour to be an aberration, they think that they are strange and not socially acceptable.","ex":{"en":"Single people are treated as an aberration and made to pay a supplement.","cn":"独身者被当成异类，而且要付一笔额外的费用。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an action or event that is very different from what usually happens or what someone usually does","cn":"一反常态﹔异常"}]},"vocab":{"pos":"n","senses":[{"en":"An aberration is a noun that means something that is not normal or is very typical at all. An example of an aberration is when the temperature hits 90 degrees in January — it's nice and warm, but it's really strange."}]},"media":{"uk":"media/ldoce/hwd/bre/d/aberration0205.mp3","us":"media/ldoce/hwd/ame/8/aberration.mp3"},"examples":[{"en":"a temporary aberration in US foreign policy","cn":"美国外交政策的短暂异常"},{"en":"a mental aberration","cn":"精神失常"}],"oxford":{"phon":"ˌæbəˈreɪʃn","pos":"noun","senses":[{"en":"a fact, an action or a way of behaving that is not usual, and that may be unacceptable","cn":"脱离常规；反常现象；异常行为","ex":{"en":"a temporary aberration of his exhausted mind","cn":"他疲惫不堪的心智的暂时失常。"}}]}}});
